37	type Pal = Record<'background'|'midground'|'foreground'|'ink'|'paper'|'hero'|'accent', string>;
38	export type P = [number, number];
39	const clamp = (v: number) => Math.min(1, Math.max(0, v));
40	const lerp = (a: number, b: number, p: number) => a + (b - a) * p;
41	const ease = (p: number) => {const q = clamp(p); return q * q * q * (10 + q * (-15 + 6 * q));};
42	/** A seeded generator: the same seed draws the same lawn, oak and debris on every frame. */
43	function rng(seed: number) {
44	 let a = seed >>> 0;
45	 return () => {a = (a + 0x6D2B79F5) >>> 0; let t = a; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296;};
46	}
