196	/** The warning banner's words, measured with the engine's own type metrics. */
197	export const BANNER_TEXT = {title: ['Flash Flood', 'Warning'], note: 'Emergency alert'};
198	/** Lay out the warning banner inside a phone `w` wide, in the phone's own units. ONE CALCULATION:
199	 * the drawing below and the episode's bound check both call this. The words keep their size and
200	 * reflow instead: the warning icon takes its own row whenever the old icon-beside-text row would
201	 * leave less than `margin` between the longest word and the banner's inner edge. Each row reports
202	 * its measured width so a check can hold it inside the banner. */
203	export function bannerLayout(w: number, font = 25, margin = 8) {
204	 const pad = 14, x0 = -w / 2 + pad, x1 = w / 2 - pad, small = Math.round(font * .76);
205	 const tw = Math.max(...BANNER_TEXT.title.map(s => widthOf(s, font, true)));
206	 const inline = x0 + 76 + tw <= x1 - margin;
207	 const tx = inline ? x0 + 76 : x0 + 12;
208	 const top = inline ? 44 : 56 + font + 6;
209	 const rows = [
210	  {text: BANNER_TEXT.title[0], x: tx, y: top, size: font},
211	  {text: BANNER_TEXT.title[1], x: tx, y: top + font + 5, size: font},
212	  {text: BANNER_TEXT.note, x: x0 + 14, y: top + 2 * font + 5 + small + 14, size: small},
213	 ].map(r => ({...r, width: widthOf(r.text, r.size, true)}));
214	 const height = rows[2].y + 18;
215	 return {x0, x1, height, inline, rows, icon: inline ? {x: x0 + 6, y: 20} : {x: x0 + 8, y: 10}, fits: rows.every(r => r.x >= x0 + margin && r.x + r.width <= x1 - margin)};
216	}
