432	 point: [[0, 0], [72, 84], [74, 84], [76, 80]], press: [[10, 8], [12, 8], [14, 8], [16, 10]],
433	 pinch: [[38, 42], [60, 70], [66, 74], [70, 76]], rest: [[24, 30], [28, 32], [30, 34], [34, 34]],
