10	/** County-true place for the directed film (October 9th, 2026).
11	 *
12	 * Place was the show's weakest axis, and every current-route film stood in a flat gradient. A board
13	 * already names each scene's county and region, ship_gate holds the region to the county's measured
14	 * Gould areas, and scripts/place_bake.py renders every region once in the Docket's carousel engine as
15	 * a SKY, one GROUND and CARDS for the things standing on it, each at its measured distance. This stage
16	 * draws the scene's region behind the episode:
17	 *
18	 *  - OUTDOORS the plate fills the frame and the camera moves through it. The ground moves by the exact
19	 *    perspective transform a camera move gives a flat ground, and each card by the rate its own
20	 *    distance gives, so the near oak slides past the refinery and nothing tears. The move comes from
21	 *    the scene's camera_strategy, as one of the manifest's profiles, never further than the share of
22	 *    the plate's measured limits the bake checked.
23	 *  - INDOORS the region is outside a window in the back wall, held still and a little out of focus,
24	 *    because a room in Abilene is lit by Abilene and its plants and dirt stay outside where they live.
25	 *    The episode's own floor and props stand in front of it as they always did.
26	 *  - OVERHEAD there is no horizon to show, and a WALL view (a diagram or a document its episode lists in
27	 *    `wall_views`) is not in a room, so for both the stage lays plain wall or the ground's own tone.
28	 *
29	 * Every camera number comes from the manifest: the plate's measured distances, focal length, limits
30	 * and the move profiles the bake checked. The arithmetic is place_bake.py's, line for line, and
31	 * tests/place_stage.mjs holds the two to the same answers. The layout constants below (the window,
32	 * the framings' zoom and focus, the window's grade) are design choices, each with its reason. */
33	
34	type V3=[number,number,number];
35	export type PlaceCamera={position:V3;right:V3;up:V3;forward:V3;fov:number;fpx:number;cx:number;cy:number};
36	type Layer={file:string;sha256:string;bytes:number};
37	type Card=Layer&{x:number;y:number;w:number;h:number;depth_m:number};
38	export type Plate={id:string;region:string;counties?:string[];also?:string[];camera:PlaceCamera;horizon_y:number;
39	 sky:Layer;ground:Layer;cards:Card[];sky_rgb:number[];ground_rgb:number[];limits:{dolly_m:number;truck_m:number;rise_m:number}};
40	export type PlaceMove={dolly:number;truck:number;rise:number};
41	type Profile=Partial<Record<'dolly'|'truck'|'rise',[number,number]>>;
42	type Manifest={policy:{version:string;effective_date:string};moves:{share:number;profiles:Record<string,Profile>};
43	 plate:{w:number;h:number};film:{w:number;h:number};plates:Record<string,Plate>};
44	const M=manifest as unknown as Manifest;
45	/** On for boards dated from the effective date, or opted in by version. Both are the manifest's, which
46	 * place_check.py reads too. */
47	export const PLACE_EFFECTIVE_DATE=M.policy.effective_date,PLACE_VERSION=M.policy.version;
48	const PW=M.plate.w,PH=M.plate.h,FW=M.film.w,FH=M.film.h;
49	const OX=(PW-FW)/2,OY=(PH-FH)/2;   // where the film frame sits inside a plate
50	
51	type PlaceBoard=Pick<DispatchProps,'date'>&{place?:{version?:string};__placeProbe?:boolean};
52	/** On for every board dated from the effective date, and for a board that opts in by version. Older
53	 * films render exactly as they shipped. */
54	export function placeActive(board:PlaceBoard):boolean{
55	 if(board.place?.version===PLACE_VERSION)return true;
56	 const date=board.date??'';
57	 return /^\d{4}-\d{2}-\d{2}/.test(date)&&date>=PLACE_EFFECTIVE_DATE;
58	}
59	/** WHICH PLATE. A region's own plate carries nothing that belongs to one place, since a Texan is not
60	 * told they live somewhere they don't: no city skyline, no refinery. A county with its own plate, as
61	 * Harris has Houston across Buffalo Bayou, stands in that one. A board may name a plate that lists
62	 * counties as `place_plate` only for a county it lists, which is how a story at a ship channel plant
63	 * gets the refineries and a story at the Medical Center doesn't. It may also name its region's own
64	 * plate, which lists none: a Harris County story out on the prairie stands in the Gulf Prairies rather
65	 * than in front of downtown, and the region's own plate can't put a county anywhere it isn't. A plate
66	 * of another region is refused. place_check.py resolves the same way. */
67	export type PlaceScene={region:string;county?:string;place_plate?:string};
68	export function plateFor(scene:PlaceScene):Plate{
69	 const inRegion=Object.values(M.plates).filter(p=>p.region===scene.region).sort((a,b)=>a.id.localeCompare(b.id));
70	 if(!inRegion.length)throw new Error('No place plate for region '+scene.region+'; bake one with scripts/place_bake.py');
71	 const county=countyName(scene.county);
72	 if(scene.place_plate){
73	  const p=M.plates[scene.place_plate];
74	  if(!p||p.region!==scene.region)throw new Error('Place plate '+scene.place_plate+' is not a '+scene.region+' plate');
75	  const scope=[...(p.counties??[]),...(p.also??[])].map(countyName);
76	  if(scope.length&&!scope.includes(county))throw new Error('Place plate '+p.id+' is not for '+scene.county+' County');
77	  return p;
78	 }
79	 const own=inRegion.find(p=>(p.counties??[]).map(countyName).includes(county));
80	 const base=inRegion.find(p=>!p.counties?.length&&!p.also?.length);
81	 if(!own&&!base)throw new Error('Region '+scene.region+' has no plate of its own');
82	 return (own??base)!;
83	}
