85	// ---- the camera, place_bake.py's arithmetic ------------------------------------------------------
86	type M3=number[];   // a 3x3 matrix, row major
87	const mul=(a:M3,b:M3):M3=>[0,1,2].flatMap(r=>[0,1,2].map(c=>a[r*3]*b[c]+a[r*3+1]*b[3+c]+a[r*3+2]*b[6+c]));
88	const dot=(a:number[],b:number[])=>a[0]*b[0]+a[1]*b[1]+a[2]*b[2];
89	const translate=(x:number,y:number):M3=>[1,0,x,0,1,y,0,0,1];
90	const scaleAbout=(s:number,x:number,y:number):M3=>[s,0,(1-s)*x,0,s,(1-s)*y,0,0,1];
91	export function moveVector(cam:PlaceCamera,m:PlaceMove):V3{
92	 const f=cam.forward,n=Math.hypot(f[0],f[2])||1,fh=[f[0]/n,0,f[2]/n];
93	 return [m.truck*cam.right[0]+m.dolly*fh[0],m.truck*cam.right[1]+m.rise,m.truck*cam.right[2]+m.dolly*fh[2]];
94	}
95	export function cameraMove(cam:PlaceCamera,m:PlaceMove):V3{
96	 const v=moveVector(cam,m);
97	 return [dot(cam.right,v),-dot(cam.up,v),dot(cam.forward,v)];
98	}
99	/** K (I + m n^T / h) K^-1: where a pixel of the ground plane goes when the camera moves. */
100	export function groundHomography(cam:PlaceCamera,mv:PlaceMove):M3{
101	 const m=cameraMove(cam,mv),n=[cam.right[1],-cam.up[1],cam.forward[1]],h=cam.position[1],f=cam.fpx;
102	 if(!(h>0))throw new Error('Place camera stands at or under its ground');
103	 const K=[f,0,cam.cx,0,f,cam.cy,0,0,1],Ki=[1/f,0,-cam.cx/f,0,1/f,-cam.cy/f,0,0,1];
104	 const A=[0,1,2].flatMap(r=>[0,1,2].map(c=>(r===c?1:0)+m[r]*n[c]/h));
105	 return mul(mul(K,A),Ki);
106	}
107	/** A card at `depth` metres scales about the centre and shifts. */
108	export function cardMatrix(cam:PlaceCamera,depth:number,mv:PlaceMove):M3{
109	 const m=cameraMove(cam,mv),d=Math.max(depth-m[2],1e-3),s=depth/d;
110	 return [s,0,(1-s)*cam.cx-cam.fpx*m[0]/d,0,s,(1-s)*cam.cy-cam.fpx*m[1]/d,0,0,1];
111	}
112	export function applyM3(H:M3,p:[number,number]):[number,number]{
113	 const w=H[6]*p[0]+H[7]*p[1]+H[8];
114	 return [(H[0]*p[0]+H[1]*p[1]+H[2])/w,(H[3]*p[0]+H[4]*p[1]+H[5])/w];
115	}
116	const ease=(u:number)=>{const p=Math.max(0,Math.min(1,u));return p*p*(3-2*p);};
117	/** The scene's camera, as one of the manifest's profiles at a share of the plate's measured limits. */
118	export function placeMove(plate:Plate,strategy:string|undefined,u:number):PlaceMove{
119	 const prof=strategy?M.moves.profiles[strategy]:undefined,move={dolly:0,truck:0,rise:0};
120	 if(!prof)return move;
121	 const p=ease(u),limit={dolly:plate.limits.dolly_m,truck:plate.limits.truck_m,rise:plate.limits.rise_m};
122	 for(const axis of ['dolly','truck','rise'] as const){
123	  const r=prof[axis];
124	  if(r)move[axis]=M.moves.share*limit[axis]*(r[0]+(r[1]-r[0])*p);
125	 }
126	 return move;
127	}
128	/** The depth of the ground under a frame row, for a subject standing there. */
129	export function groundDepthAt(cam:PlaceCamera,frameY:number):number{
130	 const v=frameY+OY,n=[cam.right[1],-cam.up[1],cam.forward[1]],dir=[0,(v-cam.cy)/cam.fpx,1];
131	 const t=-cam.position[1]/dot(n,dir);
132	 if(!(t>0))throw new Error('That row is on or above the horizon; nothing stands on the ground there');
